import { test, expect } from "@playwright/test";

test("registers once and restores the authenticated session", async ({ page }) => {
  const requests: string[] = []; page.on("request", r => { if (r.url().includes("/register")) requests.push(r.url()); });
  await page.goto("/register"); await page.getByLabel("Email").fill("new@example.test"); await page.getByLabel("Password").fill("correct-horse"); await page.getByRole("button", { name: "Register" }).click();
  await expect(page).toHaveURL(/dashboard/); await expect(page.getByTestId("account-email")).toHaveText("new@example.test"); expect(requests).toHaveLength(1); await page.reload(); await expect(page).toHaveURL(/dashboard/); expect(requests).toHaveLength(1);
});
